# ========================================================= # YasNum Telegram Bot - Complete Single File # ========================================================= # Requirements: # pip install pyTelegramBotAPI requests # # Environment variables: # BOT_TOKEN # FIVESIM_API_KEY # ADMIN_ID # # Optional: # SUPPORT_USERNAME # REFERRAL_REWARD # SELL_MARGIN # BANK_INFO # WALLET_INFO # # NOTE: # This is a self-contained bot.py. It uses JSON as a lightweight # database and the current FiveSIM API v1 endpoints. # ========================================================= import os import json import time import threading import traceback import http.server import socketserver from datetime import datetime, timezone from decimal import Decimal, InvalidOperation import requests import telebot from telebot import types # ========================================================= # CONFIG # ========================================================= try: import config except ImportError: config = None BOT_TOKEN = ( os.getenv("BOT_TOKEN") or getattr(config, "BOT_TOKEN", "") or "8998307482:AAGW3woMPiD5fuMnQuCvQh6z_2GTa5Wsu6w" ).strip() FIVESIM_API_KEY = ( os.getenv("FIVESIM_API_KEY") or getattr(config, "FIVESIM_API_KEY", "") ).strip() try: ADMIN_ID = int( os.getenv("ADMIN_ID") or getattr(config, "ADMIN_ID", 0) or 8097770003 ) except (ValueError, TypeError): ADMIN_ID = 8097770003 BOT_NAME = ( os.getenv("BOT_NAME") or getattr(config, "BOT_NAME", "YasNum") or "YasNum" ).strip() SUPPORT_USERNAME = ( os.getenv("SUPPORT_USERNAME") or getattr(config, "SUPPORT_USERNAME", "@Yy77501") or "@Yy77501" ).strip() try: REFERRAL_REWARD = float( os.getenv("REFERRAL_REWARD") or getattr(config, "REFERRAL_REWARD", 0.10) ) except (ValueError, TypeError): REFERRAL_REWARD = 0.10 try: SELL_MARGIN = float( os.getenv("SELL_MARGIN") or getattr(config, "SELL_MARGIN", 0.0) ) except (ValueError, TypeError): SELL_MARGIN = 0.0 BANK_INFO = ( os.getenv("BANK_INFO") or getattr(config, "BANK_INFO", "ظٹط±ط¬ظ‰ ط§ظ„طھظˆط§طµ